using System;using System.IO;using System.Reflection;using System.Windows;using System.Windows.Controls;using Conan.PluginApi;
class TextToolsPluginTests {
 static int checks,failed;static void Check(bool ok,string message){checks++;if(!ok)failed++;Console.WriteLine((ok?"PASS ":"FAIL ")+message);}
 [STAThread]static int Main(string[] args){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var root=args[0];Directory.CreateDirectory(root);var manager=new PluginManager(root);Window window=null;AdvancedRuntime advanced=null;try{string package=args[1];var manifest=PluginManager.Inspect(package);Check(manifest.Id=="text-tools","text tools separate package");manager.Install(package);Check(!manager.Enabled("text-tools"),"package installs disabled");manager.SetEnabled("text-tools",true);var tool=manager.Service<ITextToolsBackend>("text-tools");Check(tool!=null&&tool.GetType().Assembly!=typeof(SkillRuntime).Assembly,"text processing runs in separate assembly");Check(tool.Process("clean"," a \n\n b ")=="a"+Environment.NewLine+"b","clean trims and removes blank lines");Check(tool.Process("unique","a\nb\na")=="a"+Environment.NewLine+"b","dedupe retains order");Check(tool.Process("upper","Abc")=="ABC"&&tool.Process("lower","AbC")=="abc","letter case transforms");Check(tool.Process("json","{\"x\":1}").Contains("\"x\": 1"),"JSON formats");bool refused=false;try{tool.Process("upper",new string('a',100001));}catch(ArgumentException){refused=true;}Check(refused,"oversized input rejected");var runtime=new SkillRuntime(root);advanced=new AdvancedRuntime(root);var windowType=typeof(SkillRuntime).Assembly.GetType("SkillsWindow",true);window=(Window)Activator.CreateInstance(windowType,new object[]{runtime,advanced});windowType.GetField("Plugins").SetValue(window,manager);var field=windowType.GetField("text",BindingFlags.Instance|BindingFlags.NonPublic);var input=(TextBox)field.GetValue(window);input.Text="  hello \n\n";var method=windowType.GetMethod("TransformPlugin",BindingFlags.Instance|BindingFlags.NonPublic);method.Invoke(window,new object[]{"clean"});Check(input.Text=="hello","actual page uses plugin output");manager.SetEnabled("text-tools",false);refused=false;try{method.Invoke(window,new object[]{"upper"});}catch(TargetInvocationException e){refused=e.InnerException is ArgumentException;}Check(refused&&input.Text=="hello","disabled package cannot process or alter text");string settings=Path.Combine(root,"user-data.txt");File.WriteAllText(settings,"keep");manager.Uninstall("text-tools");Check(File.ReadAllText(settings)=="keep"&&!Directory.Exists(Path.Combine(root,"plugins","installed","text-tools")),"uninstall preserves unrelated data");var migration=new PluginManager(Path.Combine(root,"migration"));string hash=PluginManager.Hash(File.ReadAllBytes(package));Check(migration.BootstrapAddedFeature(package,hash,"text-tools",true)&&migration.Enabled("text-tools"),"existing users migrate once");migration.Uninstall("text-tools");Check(!migration.BootstrapAddedFeature(package,hash,"text-tools",true)&&migration.List().Length==0,"uninstall survives later startup");migration.Dispose();}catch(Exception e){Console.WriteLine("FAIL "+e);failed++;}finally{if(window!=null)window.Close();if(advanced!=null)advanced.Dispose();manager.Dispose();app.Shutdown();}Console.WriteLine("checks="+checks+" failures="+failed);return failed==0?0:1;}
}
